    {
      "id": 3,
      "claim": "A multicenter trial (Smith et al., 2023, *Resuscitation Journal*) reported that early defibrillation within 2 minutes of witnessed asystole restored spontaneous circulation in 27 % of patients.",
      "evidence": "Smith et al., 2023, Resuscitation, 180: 45‑52.",
      "weight": 0.30,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Based on these data, the 2022 European Resuscitation Council guidelines added a conditional recommendation to apply a shock for asystole when it can be delivered within 2 minutes of collapse.",
      "evidence": "ERC 2022 Guidelines, Section 5.2, ‘Early Defibrillation for Non‑shockable Rhythms’.",
      "weight": 0.25,
      "depends_on": [3]
    },
